function toast(msg){let e=document.getElementById('toast');e.textContent=msg;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2900)}
function go(r){if(route===r){render();window.scrollTo(0,0)}else location.hash=r}
function modal(html){document.getElementById('modal').innerHTML=`<button class="modal-close" onclick="closeModal()" aria-label="关闭">×</button>${html}`;document.getElementById('overlay').classList.add('open');document.getElementById('modal').querySelector('input,button')?.focus()}
