function productCard(p){return `<article class="product"><div class="product-image"><button onclick="detail(${p.id})" aria-label="查看${E(p.name)}"><img src="assets/${p.img}" alt="${E(p.name)}" loading="lazy"></button><span class="product-tag">${E(p.tag)}</span></div><div class="product-content"><div class="product-origin">${E(p.origin)} &nbsp; / &nbsp; ${E(p.unit)}</div><button class="product-title" onclick="detail(${p.id})">${E(p.name)}</button><p class="product-desc">${E(p.desc)}</p><div class="product-price"><span class="price"><small>¥</small>${Y(p.price)}</span><span class="old">¥${Y(p.old)}</span><button class="add-button" onclick="addCart(${p.id})" aria-label="加购${E(p.name)}">+</button></div><div class="product-foot"><button onclick="shareProduct(${p.id})">分享预计赚 ¥${M(p.price*.1)} ↗</button><span>已售 ${p.sold}</span></div></div></article>`}
function visibleProducts(limit=0){let list=db.products.filter(p=>p.active&&(category==='全部'||p.category===category)&&(!search||(p.name+p.desc+p.origin).includes(search)));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.sold-a.sold);if(limit)list=list.slice(0,limit);return list.length?list.map(productCard).join(''):`<div class="empty">${I('search')}没有找到相关鲜果<button class="btn light" onclick="search='';category='全部';render()">清除筛选</button></div>`}
