function shop(){return title('好果子，慢慢挑','每一份自然的鲜甜，都经过认真挑选。')+`<div class="shop-layout"><aside class="category-panel"><h3>鲜果分类</h3>${[['全部','🍃'],['当季鲜果','🍊'],['进口优选','🍌'],['鲜果礼盒','🎁'],['组合套餐','🥝']].map(([c,em])=>`<button class="${category===c?'active':''}" onclick="category='${c}';render()"><span>${em}</span>${c}</button>`).join('')}</aside><section><div class="campaign-strip"><span class="big-emoji">🌿</span><div><strong>秋日鲜果节 · 满99减10</strong><p>当季好果上新，会员与优惠券还可再省一点</p></div><button class="link" onclick="go('coupons')">先领券 ↗</button></div><div class="sort-bar"><span>${search?'搜索「'+E(search)+'」 · ':''}共 ${db.products.filter(p=>p.active&&(category==='全部'||p.category===category)&&(!search||(p.name+p.desc+p.origin).includes(search))).length} 款鲜果</span><select aria-label="商品排序" onchange="sort=this.value;render()"><option value="recommended" ${sort==='recommended'?'selected':''}>综合推荐</option><option value="low" ${sort==='low'?'selected':''}>价格从低到高</option><option value="high" ${sort==='high'?'selected':''}>销量优先</option></select></div><div class="products">${visibleProducts()}</div></section></div>`}
function detail(id){let p=P(id);if(!p.active){toast('该商品已下架');return}detailQty=1;detailSpec=p.unit;modal(`<img class="detail-image" src="assets/${p.img}" alt="${E(p.name)}"><div class="between"><span class="product-origin">${E(p.origin)}</span><span class="pill">产地直采</span></div><h2 style="margin:9px 0 13px">${E(p.name)}</h2><span class="price"><small>¥</small>${Y(p.price)}</span> <span class="old">¥${Y(p.old)}</span><div class="detail-meta"><span class="pill">会员95折</span><span class="pill orange">满99减10</span><button class="pill" onclick="closeModal();go('coupons')">领券再省15元 ↗</button></div><p>${E(p.desc)}。鲜度承诺，坏果售后无忧。</p><div class="modal-divider"></div><p>选择规格</p><div class="detail-options"><button class="active">${E(p.unit)}</button></div><div class="detail-qty"><span>购买数量 <small>库存 ${p.stock} 份</small></span><div class="qty"><button onclick="detailQty=Math.max(1,detailQty-1);document.getElementById('detail-q').textContent=detailQty">−</button><span id="detail-q">1</span><button onclick="detailQty=Math.min(${p.stock},detailQty+1);document.getElementById('detail-q').textContent=detailQty">+</button></div></div><div class="modal-buttons"><button class="btn light" onclick="addCart(${id},detailQty);closeModal()">加入购物车</button><button class="btn" onclick="buyNow(${id})">立即购买</button></div><button class="link" style="margin-top:20px;width:100%;justify-content:center" onclick="shareProduct(${id})">${I('share')} 分享给好友，预计赚 ¥${M(p.price*.1)}</button>`)}
function addCart(id,q=1){let p=P(id);if(!p?.active){toast('商品已下架');return}let c=db.cart.find(c=>c.id===id);let next=(c?.q||0)+q;if(next>p.stock){toast('购买数量超过库存');return}if(c){c.q=next;c.selected=true}else db.cart.push({id,q,selected:true,unit:p.unit});persist();updateBadges();toast('已加入购物车，鲜甜为你留好')}
function updateBadges(){document.querySelectorAll('.badge.cart-count').forEach(e=>e.textContent=cartCount());document.querySelectorAll('.cart-tool .badge,.bottom-nav .badge').forEach(e=>e.textContent=cartCount())}
function buyNow(id){db.cart.forEach(c=>c.selected=false);addCart(id,detailQty);persist();closeModal();go('checkout')}
function changeQty(id,d){let c=db.cart.find(c=>c.id===id);if(c.q+d<1)return;if(c.q+d>P(id).stock){toast('已达到库存上限');return}c.q+=d;persist();render()}
function selectCart(id,v){let c=db.cart.find(c=>c.id===id);if(c)c.selected=v;persist();render()}
function selectAll(v){db.cart.forEach(c=>c.selected=v);persist();render()}
function removeCart(id){db.cart=db.cart.filter(c=>c.id!==id);persist();render();toast('已移出购物车')}
function removeSelected(){if(!db.cart.some(c=>c.selected)){toast('请先勾选商品');return}db.cart=db.cart.filter(c=>!c.selected);persist();render();toast('已移除所选商品')}
function cartTotals(){let items=db.cart.filter(c=>c.selected&&P(c.id)?.active),sub=items.reduce((n,c)=>n+P(c.id).price*c.q,0),member=db.vip?Math.round(sub*.05*100)/100:0,base=sub-member;let now='2026-10-31';let activity=Math.min(base,Math.max(0,...db.activities.filter(a=>a.type==='满减活动'&&a.active&&a.start<=now&&a.end>=now&&base>=a.min).map(a=>a.off)));let eligible=couponDefs.filter(c=>db.coupons.includes(c.id)&&!db.usedCoupons.includes(c.id)&&base-activity>=c.min);let coupon=chosenCoupon==='auto'?eligible.sort((a,b)=>b.value-a.value)[0]:eligible.find(c=>c.id===chosenCoupon);let shipping=items.length&&(deliveryMode!=='门店自提')&&sub<db.settings.free?db.settings.shipping:0;return {items,sub,member,activity,coupon,shipping,total:Math.max(0,Math.round((base-activity-(coupon?.value||0)+shipping)*100)/100),saved:member+activity+(coupon?.value||0)}}
function addressCard(){let a=addresses[addressIndex];return `<div class="address-card"><span class="address-icon">${I('pin')}</span><div><strong>${E(a.name)} &nbsp; ${a.phone} <span class="pill tiny">${a.label}</span></strong><p>${E(a.address)}</p></div><button class="link" onclick="chooseAddress()">更换 ${I('chevron')}</button></div>`}
function summary(checkout=false){let t=cartTotals();return `<aside class="panel summary-panel"><h3>订单明细</h3><div class="summary-lines"><div class="summary-line"><span>商品总额</span><b>¥${M(t.sub)}</b></div><div class="summary-line discount"><span>鲜享会员95折</span><b>− ¥${M(t.member)}</b></div><div class="summary-line discount"><span>活动满减</span><b>− ¥${M(t.activity)}</b></div><div class="summary-line discount"><span>优惠券</span><button onclick="chooseCoupon()">${t.coupon?'− ¥'+t.coupon.value:'选择优惠券'} ${I('chevron')}</button></div><div class="summary-line"><span>配送费用</span><b>${t.shipping?'¥'+M(t.shipping):'免配送费'}</b></div></div><div class="summary-total"><div class="between"><strong>合计</strong><span class="price"><small>¥</small>${M(t.total)}</span></div><p class="saving">共为你节省 ¥${M(t.saved)}</p></div><button class="btn" onclick="${checkout?'submitOrder()':"if(cartTotals().items.length)go('checkout');else toast('请先选择要结算的商品')"}" ${!t.items.length?'disabled':''}>${checkout?'确认演示订单':'去结算 ('+t.items.reduce((n,c)=>n+c.q,0)+')'} ${I('arrow')}</button><p class="summary-note">${checkout?'仅创建演示订单，不会扣款或发货':'放心挑选，每一份新鲜都有保障'}</p></aside>`}
function cartPage(){let t=cartTotals(),all=db.cart.length&&db.cart.every(c=>c.selected);return title('购物车','把喜欢的鲜甜，一起带回家。')+(db.cart.length?`<div class="cart-layout"><section>${addressCard()}<div class="panel cart-panel"><div class="cart-top"><label class="flex gap"><input type="checkbox" class="check" ${all?'checked':''} onchange="selectAll(this.checked)">全选 <span class="muted tiny">共 ${cartCount()} 件商品</span></label><button class="link" onclick="removeSelected()">删除所选</button></div><div class="cart-promo"><span class="pill">满减</span><span>${t.sub-t.member>=99?'已享满99减10，让新鲜更实惠':'再购 ¥'+M(Math.max(0,(99-(t.sub-t.member))/(db.vip?.95:1)))+'，可享满99减10'}</span><button onclick="category='全部';go('shop')">去凑单 ›</button></div>${db.cart.map(c=>{let p=P(c.id);return `<article class="cart-row"><input class="check" type="checkbox" ${c.selected?'checked':''} onchange="selectCart(${c.id},this.checked)" aria-label="选择${E(p.name)}"><img src="assets/${p.img}" alt="${E(p.name)}"><div class="cart-item-info"><h3>${E(p.name)}</h3><button class="spec-button" onclick="editSpec(${c.id})">${E(c.unit)} ${I('down')}</button><span class="pill">${p.active?'会员专享95折':'商品已下架'}</span></div><span class="cart-price">¥${M(p.price)}</span><div class="cart-controls"><div class="qty"><button onclick="changeQty(${c.id},-1)" aria-label="减少${E(p.name)}">−</button><span>${c.q}</span><button onclick="changeQty(${c.id},1)" aria-label="增加${E(p.name)}">+</button></div><button class="remove" onclick="removeCart(${c.id})">${I('trash')}移除</button></div></article>`}).join('')}<div class="cart-foot"><label class="flex gap"><input class="check" type="checkbox" ${all?'checked':''} onchange="selectAll(this.checked)">全选</label><span>已选 ${t.items.reduce((n,c)=>n+c.q,0)} 件 · 满 ¥${db.settings.free} 免配送费</span></div></div></section>${summary()}</div>`:`<div class="panel empty">${I('cart')}购物车还空着，装一点新鲜吧。<br><button class="btn" onclick="go('shop')">去挑选鲜果</button></div>`)+section('你可能也喜欢','再添一点，甜蜜刚刚好')+`<div class="products">${db.products.filter(p=>p.active).slice(0,4).map(productCard).join('')}</div>`}
function editSpec(id){let c=db.cart.find(c=>c.id===id),p=P(id);modal(`<h2>商品规格</h2><div class="checkout-item"><img src="assets/${p.img}" alt="${E(p.name)}"><h4>${E(p.name)}</h4></div><div class="detail-options"><button class="active">${E(p.unit)}</button></div><p>当前商品提供以上规格，套餐内的子商品详情可在组合套餐中查看。</p><button class="btn wide" onclick="closeModal()">确认规格</button>`)}
