function addressForm(){modal(`<h2>新增收货地址</h2><form onsubmit="event.preventDefault();saveAddress(this)"><label class="field">收货人<input name="name" required maxlength="20" placeholder="请输入姓名"></label><label class="field">手机号<input name="phone" required pattern="1[0-9]{10}" placeholder="11位手机号" inputmode="tel"></label><label class="field">详细地址<input name="address" required minlength="6" maxlength="100" placeholder="省市区、街道和门牌号"></label><button class="btn wide">保存地址</button></form>`)}
