function chooseCoupon(){let t=cartTotals();modal(`<h2>选择优惠券</h2><button class="address-option ${chosenCoupon==='auto'?'active':''}" onclick="chosenCoupon='auto';closeModal();render()"><h3>自动使用最优优惠券</h3><p>帮你算好，省得刚刚好。</p></button>${couponDefs.filter(c=>db.coupons.includes(c.id)&&!db.usedCoupons.includes(c.id)).map(c=>{let ok=t.sub-t.member-t.activity>=c.min;return `<button class="address-option ${chosenCoupon===c.id?'active':''}" ${ok?'':'disabled'} onclick="chosenCoupon='${c.id}';closeModal();render()"><h3>¥${c.value} · ${c.title}</h3><p>满 ¥${c.min} 可用 ${ok?'':'｜ 未达到使用门槛'}</p></button>`}).join('')}<button class="link" onclick="chosenCoupon='none';closeModal();render()">本次不使用优惠券</button>`)}
function checkout(){let t=cartTotals();if(!t.items.length)return title('确认订单','请先选购喜欢的鲜果。')+`<div class="panel empty">${I('bag')}还没有待结算商品<br><button class="btn" onclick="go('shop')">去选购</button></div>`;return title('确认订单','最后一步，把新鲜送到你身边。')+`<div class="checkout-layout"><section>${addressCard()}<div class="panel"><h3>配送方式</h3><div class="delivery-options">${['同城配送','门店自提','快递配送'].map(d=>`<button class="${deliveryMode===d?'active':''}" onclick="deliveryMode='${d}';render()">${d}</button>`).join('')}</div><p class="small muted" style="margin-top:15px;font-size:10px">${deliveryMode==='门店自提'?'取货门店：'+E(db.settings.name)+' · 营业时间 '+E(db.settings.hours):'预计次日送达 · 配送前会联系收货人'}</p></div><div class="panel"><div class="panel-title"><h3>商品清单</h3><span class="tiny muted">共 ${t.items.reduce((n,c)=>n+c.q,0)} 件</span></div>${t.items.map(c=>{let p=P(c.id);return `<div class="checkout-item"><img src="assets/${p.img}" alt="${E(p.name)}"><div><h4>${E(p.name)}</h4><p>${E(c.unit)}</p></div><strong>¥${M(p.price)}<small>×${c.q}</small></strong></div>`}).join('')}</div><div class="panel"><label class="field" style="margin:0">订单备注<textarea id="order-note" maxlength="100" placeholder="有什么想告诉我们的？例如：请放在门口"></textarea></label></div></section>${summary(true)}</div>`}
function submitOrder(){let t=cartTotals();if(!t.items.length)return;let first=t.items[0],id='GY'+Date.now(),a=addresses[addressIndex];db.orders.unshift({id,name:t.items.map(c=>P(c.id).name).join('、'),product:first.id,qty:t.items.reduce((n,c)=>n+c.q,0),total:t.total,status:'待付款',date:new Date().toLocaleString('sv-SE').slice(0,16),customer:a.name,phone:a.phone,delivery:deliveryMode,address:a.address,note:document.getElementById('order-note')?.value||'',demo:true});if(t.coupon)db.usedCoupons.push(t.coupon.id);t.items.forEach(c=>{let p=P(c.id);p.stock-=c.q});db.cart=db.cart.filter(c=>!c.selected);persist();go('success');window.lastOrderId=id}
