function member(){let order=db.orders.find(o=>o.status==='待发货')||db.orders[0];let p=P(order.product);return `<section class="member-profile"><div class="profile-info"><span class="profile-avatar">林</span><div><h2>${E(db.profile.name)} <span style="font-size:15px">🌿</span></h2><span class="pill">${I('crown')} ${db.vip?'鲜享金卡会员':'果屿体验会员'}</span><p>果屿陪你，认真吃果的第 128 天。</p></div></div><button class="link" onclick="profileForm()">编辑资料 ${I('chevron')}</button><div class="vip-mini"><div><h3>GUOYU CLUB</h3><p>专享95折 · 每月会员券 · 鲜享礼遇</p></div><button class="btn" onclick="vipDetail()">查看权益 ↗</button></div></section><div class="member-assets">${[['¥'+Y(db.balance),'余额','wallet'],[db.points,'积分','points'],[db.coupons.filter(id=>!db.usedCoupons.includes(id)).length,'优惠券','coupons'],[M(Math.max(0,39.8-db.withdraw.reduce((n,w)=>n+w.amount,0))),'可提现佣金','referral']].map(([n,t,r])=>`<button class="asset" onclick="${r==='wallet'?"ledger('balance')":r==='points'?"pointsPage()":`go('${r}')`}"><strong>${n}</strong><span>${t} ›</span></button>`).join('')}</div><div class="member-columns"><section><div class="panel"><div class="panel-title"><h3>我的订单</h3><button class="link" onclick="orderTab='全部';go('orders')">全部订单 ${I('chevron')}</button></div><div class="order-status-grid">${[['wallet','待付款'],['box','待发货'],['truck','待收货'],['star','待评价'],['refresh','售后中']].map(([ic,t])=>`<button onclick="orderTab='${t}';go('orders')">${I(ic)}<span>${t==='售后中'?'退款 / 售后':t}</span>${db.orders.filter(o=>o.status===t).length?`<b class="badge">${db.orders.filter(o=>o.status===t).length}</b>`:''}</button>`).join('')}</div><div class="member-order"><div class="between"><span>${E(order.id)}</span><span class="orange">${E(order.status)}</span></div><div class="member-order-body"><img src="assets/${p.img}" alt="${E(order.name)}"><div><h4>${E(order.name)}</h4><p>共 ${order.qty} 件 · 实付 ¥${M(order.total)}</p></div><button class="btn outline" onclick="orderDetail('${order.id}')">查看详情</button></div></div></div><div class="panel"><div class="panel-title"><h3>常用服务</h3></div><div class="service-grid">${[['pin','收货地址','chooseAddress()'],['heart','我的收藏',"favoritePage()"],['clock','浏览足迹',"favoritePage('浏览足迹')"],['gift','积分好礼','pointsPage()'],['share','推荐有礼',"go('referral')"],['service','专属客服','contact()'],['shield','售后保障',"infoPage('鲜度有保障','收到水果后如遇坏果，请保留商品照片，在订单详情中申请售后。审核模板可体验提交售后申请的流程。')"],['settings','账户设置','profileForm()']].map(([ic,t,action])=>`<button onclick="${action}">${I(ic)}${t}</button>`).join('')}</div></div></section><aside class="member-side"><div class="referral-mini"><div class="eyebrow" style="color:#92a57b;font-size:8px">SWEET TO SHARE</div><h3 style="margin-top:14px">你的分享，自带甜蜜回报</h3><p>让好果遇见好朋友，每一次推荐都有回响。</p><div class="between"><div><p style="margin-bottom:5px;font-size:9px">累计推荐收益</p><span class="metric-number">¥286.50</span></div><button class="btn small" onclick="go('referral')">进入推荐中心 ↗</button></div></div><div class="panel member-side-list">${[['coupon','会员专享券','coupons'],['gift','超值鲜果套餐','bundles'],['people','邀请好友尝鲜','referral']].map(([ic,t,r])=>`<button onclick="go('${r}')"><span class="flex gap">${I(ic)}${t}</span>${I('chevron')}</button>`).join('')}<button onclick="contact()"><span class="flex gap">${I('service')}联系客服</span>${I('chevron')}</button></div></aside></div>`}
function vipDetail(){modal(`<div class="modal-hero"><div class="eyebrow">GUOYU CLUB</div><h3 style="margin-top:13px">好好吃果，也好好宠你。</h3><p>鲜享金卡会员 · 让新鲜成为习惯</p></div>${[['会员专享95折','日常鲜果商品结算时享专属优惠'],['每月会员好券','领取专属优惠券，尝鲜更实惠'],['专属客服与售后','每份新鲜都值得被认真对待']].map(([t,s])=>`<div class="ledger-row"><div><strong>${t}</strong><p>${s}</p></div>${I('check')}</div>`).join('')}<button class="btn wide" onclick="db.vip=!db.vip;persist();closeModal();render();toast('已切换为'+(db.vip?'金卡会员':'普通会员')+'，可审核不同身份的结算')">${db.vip?'切换普通会员体验':'开启会员体验'}</button><p style="margin-top:12px">仅切换模板会员状态，不涉及付费开卡。</p>`)}
function profileForm(){modal(`<h2>账户资料</h2><form onsubmit="saveProfile(event)"><label class="field">昵称<input name="name" required value="${E(db.profile.name)}" maxlength="20"></label><label class="field">手机号<input value="138****0826" readonly></label><label class="field">生日<input name="birthday" type="date" value="${E(db.profile.birthday)}"></label><button class="btn wide">保存资料</button></form>`)}
function ledger(){modal(`<h2>我的余额</h2><div class="modal-hero"><p>可用余额</p><h3 style="margin-top:10px">¥${M(db.balance)}</h3><p>模板账户余额，无实际资金价值</p></div><div class="ledger-row"><div>会员储值赠送<p>2026-10-20 09:30</p></div><b class="green">+ ¥300.00</b></div><div class="ledger-row"><div>订单支付<p>2026-10-22 16:28</p></div><b>− ¥32.00</b></div><button class="btn outline wide" onclick="infoPage('储值功能预览','正式开发时可设置储值档位、赠送金额、使用范围和退款规则。本模板暂不接入充值收款。')">查看储值方案</button>`)}
function pointsPage(){modal(`<h2>积分好礼</h2><div class="between"><p>当前积分</p><strong class="price" style="color:var(--green)">${db.points}</strong></div><div class="modal-divider"></div><div class="coupon-top" style="border-radius:10px"><span class="coupon-value"><small>¥</small>5</span><div><h3>鲜果抵用券</h3><p>500积分兑换 · 满29元可用</p></div></div><button class="btn wide" onclick="redeemPoints()" ${db.coupons.includes('points')||db.points<500?'disabled':''}>${db.coupons.includes('points')?'本期已兑换':'500积分立即兑换'}</button><p style="margin-top:15px">每个演示账户本期限兑一次。积分和优惠券会保存在当前浏览器。</p>`)}
function redeemPoints(){if(db.points<500||db.coupons.includes('points'))return;db.points-=500;db.coupons.push('points');persist();closeModal();render();toast('兑换成功，优惠券已存入账户')}
function favoritePage(t='我的收藏'){modal(`<h2>${t}</h2>${db.products.slice(0,3).map(p=>`<button class="checkout-item" style="width:100%;text-align:left" onclick="detail(${p.id})"><img src="assets/${p.img}" alt="${E(p.name)}"><div><h4>${E(p.name)}</h4><p>¥${M(p.price)}</p></div></button>`).join('')}`)}
function contact(){infoPage('果屿专属客服',`服务时间：${db.settings.hours}<br>联系电话：${E(db.settings.phone)}<br>订单问题可在订单详情中提交售后。当前为模板客服入口，未连接真人客服。`)}
function infoPage(t,html){modal(`<h2>${t}</h2><p>${html}</p><button class="btn wide" onclick="closeModal()">我知道了</button>`)}
function ordersPage(){let list=db.orders.filter(o=>orderTab==='全部'||o.status===orderTab);return title('我的订单','每一份新鲜，都有迹可循。')+`<div class="tabs">${['全部','待付款','待发货','待收货','已完成','售后中'].map(t=>`<button class="${orderTab===t?'active':''}" onclick="orderTab='${t}';render()">${t}</button>`).join('')}</div><div class="order-list">${list.map(o=>{let p=P(o.product);return `<article class="panel order-card"><div class="order-card-head"><span>${E(o.id)} &nbsp; ${E(o.date)}</span><span class="pill ${o.status==='售后中'?'orange':''}">${o.status}</span></div><div class="order-card-body"><img src="assets/${p.img}" alt="${E(o.name)}"><div><h3>${E(o.name)}</h3><p>${p.unit} · 共 ${o.qty} 件</p><p style="margin-top:8px">${o.delivery}</p></div></div><div class="order-card-bottom"><strong>实付 ¥${M(o.total)}</strong><button class="btn outline" onclick="orderDetail('${o.id}')">订单详情</button>${o.status==='待收货'?`<button class="btn" onclick="changeOrder('${o.id}','已完成')">确认收货</button>`:o.status==='待付款'?`<button class="btn" onclick="demoPay('${o.id}')">演示付款</button>`:`<button class="btn light" onclick="addCart(${o.product});go('cart')">再买一单</button>`}</div></article>`}).join('')||`<div class="panel empty">${I('orders')}这个分类下还没有订单。</div>`}</div>`}
function orderDetail(id){let o=db.orders.find(o=>o.id===id);modal(`<h2>订单详情</h2><div class="notice">${I('truck')}当前状态：${E(o.status)} · ${E(o.delivery)}</div><div class="checkout-item"><img src="assets/${P(o.product).img}" alt="${E(o.name)}"><div><h4>${E(o.name)}</h4><p>共 ${o.qty} 件</p></div></div><div class="summary-line"><span>订单编号</span><span>${E(o.id)}</span></div><div class="summary-line"><span>下单时间</span><span>${E(o.date)}</span></div><div class="summary-line"><span>收货人</span><span>${E(o.customer)} ${E(o.phone)}</span></div><p>${E(o.address)}</p>${o.note?`<p>备注：${E(o.note)}</p>`:''}<div class="summary-line"><span>实付金额</span><b>¥${M(o.total)}</b></div><div class="modal-buttons"><button class="btn outline" onclick="contact()">联系客服</button>${o.status==='待付款'?`<button class="btn" onclick="demoPay('${id}')">演示付款</button>`:o.status==='待收货'?`<button class="btn" onclick="changeOrder('${id}','已完成')">确认收货</button>`:!['售后中','已退款','已取消'].includes(o.status)?`<button class="btn" onclick="afterSale('${id}')">申请售后</button>`:`<button class="btn" onclick="closeModal()">关闭详情</button>`}</div><p style="margin-top:14px">演示订单，不产生真实交易。</p>`)}
function changeOrder(id,status){db.orders.find(o=>o.id===id).status=status;persist();closeModal();render();toast('订单状态已更新为'+status)}
function demoPay(id){modal(`<h2>演示付款</h2><p>订单 ${E(id)}<br>模板阶段不调用微信支付，不会扣款。可模拟支付成功，检查后续订单和商家后台流程。</p><button class="btn wide" onclick="changeOrder('${id}','待发货')">模拟支付成功</button>`)}
function afterSale(id){modal(`<h2>申请售后</h2><form onsubmit="event.preventDefault();changeOrder('${id}','售后中')"><label class="field">售后类型<select><option>退款</option><option>退货退款</option><option>坏果补偿</option></select></label><label class="field">问题说明<textarea required minlength="4" placeholder="请描述商品问题，至少4个字"></textarea></label><button class="btn wide">提交演示售后申请</button></form>`)}
function bundlesPage(){return title('一箱好果，刚好合拍','搭配好的新鲜，省心也省一点。')+`<div class="campaign-strip"><span class="big-emoji">🥝</span><div><strong>一起买，更划算</strong><p>固定搭配 / 自选组合 · 不同的喜欢，一起满足</p></div><span class="pill">鲜果组合计划</span></div><div class="bundle-grid">${[{id:6,title:'周末双拼 · 甜蜜分享装',sub:'适合2–3人 · 一次尝到两份甜',items:['夏黑葡萄 2斤 × 1份','四川果冻橙 5斤 × 1份'],price:65.9,old:69.8,img:'grapes.jpg',tag:'固定组合'},{id:4,title:'一周鲜果 · 家庭缤纷箱',sub:'适合3–4人 · 每天都有小惊喜',items:['精选6种时令鲜果','净重约8斤，产地直采'],price:89,old:128,img:'box.jpg',tag:'家庭优选'},{id:0,title:'我的鲜果箱 · 3选2',sub:'喜欢的味道，自己来搭配',items:['葡萄 / 果冻橙 / 高山香蕉','任选两份，组合价更实惠'],price:45.9,old:49.8,img:'orange.jpg',tag:'自选组合'},{id:3,title:'莓好时光 · 奶油草莓双盒',sub:'一份自己吃，一份分享给喜欢的人',items:['红颜草莓 2盒 × 1份','精选大果，颗颗香甜'],price:49.9,old:69.9,img:'strawberry.jpg',tag:'当季推荐'}].map(b=>`<article class="bundle-card"><img src="assets/${b.img}" alt="${b.title}"><div class="bundle-card-content"><span class="pill">${b.tag}</span><h3>${b.title}</h3><p>${b.sub}</p><ul>${b.items.map(t=>`<li>${t}</li>`).join('')}</ul><span class="price"><small>¥</small>${b.price}<span class="old">¥${b.old}</span></span><button class="btn" onclick="${b.id?'bundleDetail('+b.id+')':'customBundle()'}">${b.id?'查看套餐详情':'搭配我的鲜果箱'} ${I('arrow')}</button></div></article>`).join('')}</div>`}
function bundleDetail(id){let p=P(id);modal(`<img class="detail-image" src="assets/${p.img}" alt="${E(p.name)}"><span class="pill">组合套餐</span><h2 style="margin:11px 0">${E(p.name)}</h2><p>${E(p.desc)}</p>${(id===6?['夏黑葡萄 2斤 × 1','四川果冻橙 5斤 × 1']:id===4?['6种时令鲜果，按当日鲜度搭配','总净重约8斤，家庭分享装']:['奶油草莓精选双盒装']).map(s=>`<div class="ledger-row"><span>${s}</span>${I('check')}</div>`).join('')}<div class="between" style="margin-top:23px"><span class="price"><small>¥</small>${p.price}</span><span class="pill orange">比单买省 ¥${M(p.old-p.price)}</span></div><p style="margin-top:14px">套餐子商品、规格与优惠规则供审核展示，正式开发后按子商品关联库存与履约。</p><button class="btn wide" onclick="addCart(${id});closeModal();go('cart')">整套加入购物车</button>`)}
function customBundle(){modal(`<h2>搭配你的鲜果箱</h2><p>从下面3种鲜果里选择2份，组合价 ¥45.90。</p><form onsubmit="saveCustomBundle(event)">${[1,2,5].map(id=>{let p=P(id);return `<label class="checkout-item" style="cursor:pointer"><input type="checkbox" class="check" name="fruits" value="${id}"><img src="assets/${p.img}" alt="${E(p.name)}"><div><h4>${E(p.name)}</h4><p>${E(p.unit)}</p></div></label>`}).join('')}<button class="btn wide">确认搭配并加入购物车</button></form>`)}
function saveCustomBundle(e){e.preventDefault();let ids=new FormData(e.target).getAll('fruits').map(Number);if(ids.length!==2){toast('请选择两种鲜果');return}let id=100+ids[0]*10+ids[1],p=P(id);if(!p){p={id,name:'自选双拼鲜果箱',desc:ids.map(id=>P(id).name).join('＋'),unit:ids.map(id=>P(id).unit).join('＋'),origin:'果屿 · 自由搭配',category:'组合套餐',price:45.9,old:ids.reduce((n,id)=>n+P(id).price,0),img:'box.jpg',tag:'我的专属搭配',stock:20,sold:0,active:true};db.products.push(p)}addCart(id);closeModal();go('cart')}
const referralRecords=[{name:'陈小满',order:'GY202610300016',money:4.98,status:'待结算',date:'10-30 15:16'},{name:'李知夏',order:'GY202610290018',money:8.9,status:'已结算',date:'10-29 10:32'},{name:'周青',order:'GY202610270026',money:3.99,status:'已结算',date:'10-27 18:26'}];
function referralPage(){return title('好果一起分享，好事自然发生','把喜欢推荐给朋友，每一份信任都有回响。')+`<section class="referral-hero"><div class="eyebrow"><i></i> GUOYU PARTNER PROGRAM</div><h2>你的好品味，<br>值得一份<em>甜蜜回报。</em></h2><p>邀请好友尝鲜，订单完成后享推荐佣金<br>精选好果 · 直接推荐 · 清晰可查</p><button class="btn lime" onclick="shareProduct()">生成我的邀请卡 ${I('share')}</button><span class="referral-art">🍊</span></section><div class="stats-grid">${stat('可提现佣金','¥'+M(Math.max(0,39.8-db.withdraw.reduce((n,w)=>n+w.amount,0))),'wallet','查看提现明细',"withdrawForm()")}${stat('待结算佣金','¥28.60','clock','订单完成后按规则结算')}${stat('累计推广收益','¥286.50','chart','每次推荐，都有回响')}${stat('成功邀请好友','18 人','people','已有6位好友完成首单')}</div><div class="panel"><div class="panel-title"><h3>三步，分享你的鲜果日常</h3><button class="link" onclick="referralRules()">佣金规则 ${I('info')}</button></div><div class="steps">${[['01','分享好果','生成商品海报或专属邀请链接'],['02','好友下单','好友通过分享进入商城购买'],['03','获得佣金','订单完成后结算至佣金账户']].map(([n,t,s])=>`<div class="step"><span>${n}</span><div><h4>${t}</h4><p>${s}</p></div></div>`).join('')}</div></div><div class="panel"><div class="panel-title"><h3>最近推广记录</h3><button class="link" onclick="withdrawRecords()">提现记录 ${I('chevron')}</button></div><div class="table-scroll"><table><thead><tr><th>好友</th><th>推广订单</th><th>预估佣金</th><th>状态</th><th>时间</th></tr></thead><tbody>${referralRecords.map(r=>`<tr><td><strong>${r.name}</strong></td><td>${r.order}</td><td class="orange">¥${M(r.money)}</td><td><span class="pill ${r.status==='待结算'?'orange':''}">${r.status}</span></td><td>${r.date}</td></tr>`).join('')}</tbody></table></div></div>`}
function stat(label,n,ic,sub,action=''){return `<div class="stat"><div class="stat-label"><span>${label}</span>${I(ic)}</div><div class="metric-number">${n}</div><div class="stat-bottom">${action?`<button class="link" style="font-size:9px;padding:0" onclick="${action}">${sub} ↗</button>`:sub}</div></div>`}
function referralRules(){infoPage('推荐佣金规则','本模板展示直接推荐奖励，预估佣金按商品标示价的10%展示。<br>正式结算需明确实付基数、绑定有效期和售后冻结期，退款需撤回对应佣金。<br>模板分享、收益与提现记录均为演示，不产生真实资金。')}
function shareProduct(id=0){let p=P(id);let url=location.origin+location.pathname+'?ref=guoyu-preview'+(p?'&product='+p.id:'')+'#'+(p?'shop':'home');window.sharePayload={title:p?'果屿 · '+p.name:'果屿 · 新鲜有好事',text:p?p.desc:'一起尝尝自然的甜。',url};modal(`<h2>把这份新鲜，分享给朋友</h2><div class="modal-hero">${p?`<img src="assets/${p.img}" alt="${E(p.name)}">`:''}<div class="eyebrow">GUOYU FRESH</div><h3 style="margin-top:14px">${p?E(p.name):'好果子，和好朋友分享'}</h3><p>${p?'¥'+Y(p.price)+' · 分享预计赚 ¥'+M(p.price*.1):'新鲜一起尝，甜蜜有回报'}</p></div><p>专属邀请链接</p><label class="field"><input id="share-url" readonly value="${E(url)}" onclick="this.select()"></label><div class="modal-buttons"><button class="btn light" onclick="copyShare()">复制链接</button><button class="btn" onclick="systemShare()">系统分享</button></div><p style="margin-top:17px">审核模板暂不生成微信小程序码或绑定推荐关系。站点目前仅你可访问，外部分享需另设访问权限。</p>`)}
async function copyShare(){try{await navigator.clipboard.writeText(window.sharePayload.url);toast('邀请链接已复制')}catch{document.getElementById('share-url')?.select();toast('请长按或按 Ctrl+C 复制链接')}}async function systemShare(){if(navigator.share){try{await navigator.share(window.sharePayload)}catch{toast('已取消分享，可复制链接')}}else copyShare()}
function withdrawForm(){let available=Math.max(0,39.8-db.withdraw.reduce((n,w)=>n+w.amount,0));modal(`<h2>佣金提现</h2><div class="summary-line"><span>可申请金额</span><strong class="price">¥${M(available)}</strong></div><form onsubmit="saveWithdraw(event)"><label class="field">提现金额<input name="amount" type="number" min="1" max="${available}" step="0.01" required placeholder="请输入金额"></label><label class="field">提现方式<select name="channel"><option>微信零钱</option><option>银行卡</option></select></label><p>此处只创建一笔演示申请，可在商家后台查看，不会实际转账。</p><button class="btn wide" ${available<1?'disabled':''}>提交演示申请</button></form>`)}
function saveWithdraw(e){e.preventDefault();let f=new FormData(e.target),amount=Number(f.get('amount'));let available=39.8-db.withdraw.reduce((n,w)=>n+w.amount,0);if(amount<=0||amount>available){toast('请输入可用范围内的金额');return}db.withdraw.unshift({id:Date.now(),name:'林小果',amount,channel:f.get('channel'),status:'待审核',date:new Date().toLocaleDateString('zh-CN')});persist();closeModal();render();toast('演示申请已提交，可到商家后台审核')}
function withdrawRecords(){modal(`<h2>提现记录</h2>${db.withdraw.length?db.withdraw.map(w=>`<div class="ledger-row"><div>¥${M(w.amount)} · ${w.channel}<p>${w.date}</p></div><span class="pill">${w.status}</span></div>`).join(''):'<div class="empty">还没有演示提现记录。</div>'}<button class="btn wide" onclick="withdrawForm()">申请提现</button>`)}
function adminShell(){let section=route.split('/')[1]||'dashboard',label=adminNavs.find(n=>n[0]===section)?.[1]||'经营概览';return reviewBar(true)+`<div class="admin-shell"><aside class="admin-sidebar">${brand()}<div class="admin-section-label">店铺运营 WORKSPACE</div><nav>${adminNavs.map(([id,t,ic])=>`<a href="#admin/${id}" class="${section===id?'active':''}" title="${t}">${I(ic)}<span>${t}</span></a>`).join('')}</nav><div class="sidebar-store"><strong>🌿 ${E(db.settings.name)}</strong><p>营业中 · 鲜果新零售</p><a class="link" href="#home" style="margin-top:12px;font-size:9px">查看我的商城 ↗</a></div><div class="admin-bottom"><span class="user-avatar">林</span><div><strong>店铺管理员</strong><small>审核模板 · 全部权限</small></div></div></aside><div class="admin-main"><header class="admin-header"><span><a href="#admin/dashboard">商家工作台</a> &nbsp; / &nbsp; <b>${label}</b></span><select class="mobile-admin-select" aria-label="后台页面" onchange="go('admin/'+this.value)">${adminNavs.map(([id,t])=>`<option value="${id}" ${section===id?'selected':''}>${t}</option>`).join('')}</select><div class="admin-header-tools"><button class="hide-mobile" onclick="go('home')">${I('eye')}预览商城</button><button onclick="infoPage('店铺待办','当前有 '+db.orders.filter(o=>o.status==='待发货').length+' 笔订单待发货，'+db.orders.filter(o=>o.status==='售后中').length+' 笔售后待处理。可前往订单管理查看。')" aria-label="通知">${I('bell')}</button><span class="user-avatar">林</span></div></header><main class="admin-content">${({dashboard:adminDashboard,products:adminProducts,orders:adminOrders,members:adminMembers,marketing:adminMarketing,commissions:adminCommissions,settings:adminSettings}[section]||adminDashboard)()}</main></div></div>`}
function chart(){return `<svg class="chart" viewBox="0 0 650 210" role="img" aria-label="近七日成交趋势：成交额呈增长走势，示例数据"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#b8cda0" stop-opacity=".5"/><stop offset="100%" stop-color="#d5e3bf" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140,180].map((y,i)=>`<line x1="40" x2="638" y1="${y}" y2="${y}"/><text x="0" y="${y+4}">${['8,000','6,000','4,000','2,000','0'][i]}</text>`).join('')}<path d="M45 143C95 148 105 108 144 112S210 151 242 118S310 63 342 75S407 120 442 82S510 76 542 47S606 31 635 22L635 180H45Z" fill="url(#chartFill)"/><path d="M45 162C88 164 111 137 144 147S207 152 242 139S303 127 342 135S406 106 442 121S504 103 542 114S606 89 635 96" fill="none" stroke="#cad7b8" stroke-width="2" stroke-dasharray="5 4"/><path d="M45 143C95 148 105 108 144 112S210 151 242 118S310 63 342 75S407 120 442 82S510 76 542 47S606 31 635 22" fill="none" stroke="#7c9b60" stroke-width="3"/>${[45,144,242,342,442,542,635].map((x,i)=>`<text x="${x-13}" y="205">10/${25+i}</text>`).join('')}<circle cx="635" cy="22" r="4" fill="#7c9b60" stroke="white" stroke-width="2"/></svg>`}
function adminDashboard(){return title('经营概览','早上好，林店长。一起看看今天的新鲜生意。',`<button class="btn outline small" onclick="exportData('orders')">${I('download')} 导出报表</button>`)+`<div class="stats-grid">${stat('今日成交额','¥3,826.80','wallet','<span class="up">↗ 12.8%</span> 较昨日 · 示例指标')}${stat('今日订单数','68','orders','<span class="up">↗ 8.6%</span> 较昨日 · 示例指标')}${stat('今日新增会员','24','people','<span class="up">↗ 16.2%</span> 较昨日 · 示例指标')}${stat('今日推荐成交','¥826.50','share','<span class="up">↗ 10.5%</span> 较昨日 · 示例指标')}</div><div class="admin-grid"><div class="panel"><div class="panel-title"><h3>交易趋势</h3><div class="chart-legend"><span><i></i>成交金额</span><span><i></i>上期对比</span></div></div>${chart()}<div class="chart-caption"><span>最近7天 · 示例趋势</span><span>订单均价 ¥56.28 &nbsp; 复购率 32.6%</span></div></div><div class="panel"><div class="panel-title"><h3>待办事项</h3><span class="pill">实时演示数据</span></div><div class="todo-grid">${[['待发货',db.orders.filter(o=>o.status==='待发货').length],['售后待处理',db.orders.filter(o=>o.status==='售后中').length],['待付款',db.orders.filter(o=>o.status==='待付款').length],['低库存商品',db.products.filter(p=>p.stock<100).length]].map(([t,n])=>`<button class="todo" onclick="${t==='低库存商品'?"go('admin/products')":`adminOrderTab='${t==='售后待处理'?'售后中':t}';go('admin/orders')`}"><span>${t}</span><strong>${n}</strong></button>`).join('')}</div><div class="admin-quick"><button onclick="productForm()">${I('box')}上架商品</button><button onclick="activityForm()">${I('gift')}创建活动</button><button onclick="go('admin/members')">${I('people')}会员运营</button></div></div></div><div class="admin-grid"><div class="panel admin-panel"><div class="panel-title"><h3>最近订单</h3><a class="link" href="#admin/orders">全部订单 ${I('chevron')}</a></div>${orderTable(db.orders.slice(0,4),true)}</div><div class="panel"><div class="panel-title"><h3>畅销鲜果 TOP 4</h3><span class="tiny muted">近30天 · 示例</span></div><div class="rank-list">${db.products.slice(0,4).sort((a,b)=>b.sold-a.sold).map((p,i)=>`<div class="rank-row"><span class="rank-num">${i+1}</span><img src="assets/${p.img}" alt="${E(p.name)}"><div class="rank-name">${E(p.name)}<div class="progress"><span style="width:${100-i*18}%"></span></div></div><strong>${p.sold}</strong></div>`).join('')}</div></div></div><div class="notice">${I('info')}审核模板：上方趋势和经营指标为示例，待办、订单与商品操作会在当前浏览器联动。</div>`}
function orderTable(list,brief=false){return `<div class="table-scroll"><table><thead><tr><th>订单 / 商品</th><th>客户</th><th>实付</th><th>状态</th>${brief?'':'<th>配送方式</th>'}<th>操作</th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>${E(o.id)}</strong><small style="display:block;font-size:9px;margin-top:6px;color:#a2ac94">${E(o.name)}</small></td><td>${E(o.customer)}</td><td><strong>¥${M(o.total)}</strong></td><td><span class="pill ${o.status==='售后中'||o.status==='待付款'?'orange':''}">${o.status}</span></td>${brief?'':`<td>${E(o.delivery)}</td>`}<td><div class="table-actions"><button onclick="orderDetail('${o.id}')">详情</button>${o.status==='待发货'?`<button onclick="shipForm('${o.id}')">发货</button>`:o.status==='售后中'?`<button onclick="refundConfirm('${o.id}')">处理售后</button>`:''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">没有符合条件的订单。</td></tr>'}</tbody></table></div>`}
function adminProducts(){let list=db.products.filter(p=>(!adminQuery||(p.name+p.id).includes(adminQuery))&&(adminFilter==='全部'||(adminFilter==='在售'?p.active:!p.active)));return title('商品管理','管理每一份新鲜，从产地到货架。',`<button class="btn" onclick="productForm()">＋ 新增商品</button>`)+`<div class="panel admin-panel"><div class="admin-filter"><div class="flex gap"><label class="search-field">${I('search')}<input aria-label="搜索商品" placeholder="搜索商品名称 / 编号" value="${E(adminQuery)}" oninput="adminQuery=this.value;refreshProductTable()"></label><select class="filter-select" onchange="adminFilter=this.value;render()">${['全部','在售','已下架'].map(t=>`<option ${adminFilter===t?'selected':''}>${t}</option>`).join('')}</select></div><button class="link" onclick="exportData('products')">${I('download')}导出商品</button></div><div id="admin-product-table">${productTable(list)}</div><div class="table-pagination"><span>共 ${list.length} 条商品 · 数据保存在本机</span><span><button class="page-button active">1</button></span></div></div>`}
function productTable(list){return `<div class="table-scroll"><table><thead><tr><th>商品信息</th><th>分类</th><th>售价</th><th>库存</th><th>销量</th><th>在售状态</th><th>操作</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="table-product"><img src="assets/${p.img}" alt="${E(p.name)}"><div><strong>${E(p.name)}</strong><small>ID ${p.id} · ${E(p.unit)}</small></div></div></td><td>${p.category}</td><td><strong>¥${M(p.price)}</strong></td><td>${p.stock<100?'<span class="orange">'+p.stock+'</span>':p.stock}</td><td>${p.sold}</td><td><button class="switch ${p.active?'on':''}" aria-label="${p.active?'下架':'上架'}${E(p.name)}" onclick="toggleProduct(${p.id})"></button></td><td><div class="table-actions"><button onclick="productForm(${p.id})">编辑</button><button onclick="detail(${p.id})">预览</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">没有找到商品。</td></tr>'}</tbody></table></div>`}
function refreshProductTable(){let list=db.products.filter(p=>(!adminQuery||(p.name+p.id).includes(adminQuery))&&(adminFilter==='全部'||(adminFilter==='在售'?p.active:!p.active)));document.getElementById('admin-product-table').innerHTML=productTable(list)}
function toggleProduct(id){P(id).active=!P(id).active;persist();render();toast(P(id).active?'商品已上架，商城同步显示':'商品已下架，商城同步隐藏')}
function productForm(id=0){let p=P(id)||{name:'',price:29.9,old:39.9,stock:100,unit:'5斤装',category:'当季鲜果',origin:'四川 · 眉山',desc:'自然鲜甜，产地直采',img:'orange.jpg'};modal(`<h2>${id?'编辑':'新增'}商品</h2><form onsubmit="saveProduct(event,${id})"><label class="field">商品名称<input name="name" required maxlength="35" value="${E(p.name)}" placeholder="例如：四川爱媛果冻橙"></label><div class="form-grid"><label class="field">销售价（元）<input name="price" type="number" required min="0.01" step="0.01" value="${p.price}"></label><label class="field">划线价（元）<input name="old" type="number" required min="0.01" step="0.01" value="${p.old}"></label><label class="field">库存（份）<input name="stock" type="number" required min="0" step="1" value="${p.stock}"></label><label class="field">分类<select name="category">${['当季鲜果','进口优选','鲜果礼盒','组合套餐'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">规格<input name="unit" required maxlength="25" value="${E(p.unit)}"></label><label class="field">产地<input name="origin" required maxlength="25" value="${E(p.origin)}"></label></div><label class="field">商品卖点<input name="desc" required maxlength="45" value="${E(p.desc)}"></label><label class="field">商品图片<select name="img">${[['orange.jpg','果冻橙'],['grapes.jpg','夏黑葡萄'],['strawberry.jpg','奶油草莓'],['box.jpg','鲜果礼盒'],['durian.jpg','高山香蕉']].map(([v,t])=>`<option value="${v}" ${p.img===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn wide">保存${id?'修改':'并上架'}</button></form>`)}
function saveProduct(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));f.price=Number(f.price);f.old=Number(f.old);f.stock=Number(f.stock);if(!f.name.trim()||f.old<f.price){toast('请填写有效名称，划线价不能低于售价');return}if(id)Object.assign(P(id),f);else db.products.unshift({...f,id:Math.max(...db.products.map(p=>p.id))+1,tag:'新鲜上架',sold:0,active:true});persist();closeModal();render();toast('商品已保存，商城页面已同步')}
function adminOrders(){let list=db.orders.filter(o=>(adminOrderTab==='全部'||o.status===adminOrderTab)&&(!adminQuery||(o.id+o.name+o.customer).includes(adminQuery)));return title('订单管理','从下单到收货，每一份新鲜都安排妥当。',`<button class="btn outline" onclick="exportData('orders')">${I('download')} 导出订单</button>`)+`<div class="tabs">${['全部','待付款','待发货','待收货','已完成','售后中','已退款'].map(t=>`<button class="${adminOrderTab===t?'active':''}" onclick="adminOrderTab='${t}';render()">${t} ${t==='全部'?'':db.orders.filter(o=>o.status===t).length}</button>`).join('')}</div><div class="panel admin-panel"><form class="admin-filter" onsubmit="event.preventDefault();adminQuery=this.q.value;render()"><label class="search-field">${I('search')}<input name="q" placeholder="订单号 / 商品 / 客户" value="${E(adminQuery)}" aria-label="搜索订单"></label><button class="btn small">查询</button></form>${orderTable(list)}<div class="table-pagination"><span>共 ${list.length} 笔订单</span><button class="page-button active">1</button></div></div>`}
function shipForm(id){modal(`<h2>订单发货</h2><p>${E(id)}</p><form onsubmit="event.preventDefault();changeOrder('${id}','待收货')"><label class="field" style="margin-top:20px">配送方式<select><option>同城配送</option><option>顺丰速运</option><option>京东物流</option><option>门店自提</option></select></label><label class="field">运单 / 配送编号<input required placeholder="请输入演示配送编号" maxlength="40"></label><button class="btn wide">确认演示发货</button></form>`)}
function refundConfirm(id){let o=db.orders.find(o=>o.id===id);modal(`<h2>处理售后申请</h2><div class="notice">${I('info')}客户：${E(o.customer)} · ${E(o.name)}</div><div class="summary-line"><span>申请金额</span><strong class="orange">¥${M(o.total)}</strong></div><p>本模板只演示状态流转；通过后标记为已退款，不调用支付接口。</p><div class="modal-buttons"><button class="btn outline" onclick="changeOrder('${id}','已完成')">驳回申请</button><button class="btn" onclick="changeOrder('${id}','已退款')">通过演示退款</button></div>`)}
const members=[{name:'林小果',phone:'138****0826',level:'鲜享金卡',spent:1286.5,orders:18,points:1280,tag:'高复购',date:'2026-06-25'},{name:'陈小满',phone:'139****1368',level:'鲜享银卡',spent:628.9,orders:9,points:628,tag:'家庭客群',date:'2026-08-12'},{name:'李知夏',phone:'137****3182',level:'普通会员',spent:89.8,orders:1,points:89,tag:'新客',date:'2026-10-30'},{name:'周青',phone:'135****8176',level:'鲜享银卡',spent:458.6,orders:6,points:458,tag:'礼盒偏好',date:'2026-09-02'}];
function adminMembers(){let list=members.filter(m=>(m.name+m.phone).includes(memberQuery));return title('会员管理','了解每一位顾客，让每一次回访都有温度。')+`<div class="stats-grid">${stat('累计会员','1,286','people','示例会员规模')}${stat('本月新增','168','user','较上月增长 12.8%')}${stat('会员复购率','32.6%','refresh','最近30天 · 示例')}${stat('会员客单价','¥68.50','wallet','最近30天 · 示例')}</div><div class="panel admin-panel"><form class="admin-filter" onsubmit="event.preventDefault();memberQuery=this.q.value;render()"><label class="search-field">${I('search')}<input name="q" placeholder="搜索会员昵称 / 手机号" value="${E(memberQuery)}"></label><button class="btn small">查询会员</button></form><div class="table-scroll"><table><thead><tr><th>会员</th><th>会员等级</th><th>累计消费</th><th>订单数</th><th>积分</th><th>标签</th><th>操作</th></tr></thead><tbody>${list.map(m=>`<tr><td><div class="table-product"><span class="user-avatar">${m.name[0]}</span><div><strong>${m.name}</strong><small>${m.phone}</small></div></div></td><td>${m.level}</td><td>¥${M(m.spent)}</td><td>${m.orders}</td><td>${m.name==='林小果'?db.points:m.points}</td><td><span class="pill">${m.tag}</span></td><td><div class="table-actions"><button onclick="memberDetail('${m.name}')">详情</button><button onclick="sendCoupon('${m.name}')">发券</button></div></td></tr>`).join('')}</tbody></table></div><div class="table-pagination"><span>展示 ${list.length} 位演示会员</span><button class="page-button active">1</button></div></div>`}
function memberDetail(name){let m=members.find(m=>m.name===name);modal(`<h2>会员详情 · ${m.name}</h2><div class="between"><span class="pill">${m.level}</span><span class="pill orange">${m.tag}</span></div><div class="ledger-row"><span>注册时间</span><span>${m.date}</span></div><div class="ledger-row"><span>手机号</span><span>${m.phone}</span></div><div class="ledger-row"><span>累计消费</span><strong>¥${M(m.spent)}</strong></div><div class="ledger-row"><span>订单数 / 可用积分</span><span>${m.orders} 单 / ${m.name==='林小果'?db.points:m.points} 分</span></div><button class="btn wide" onclick="sendCoupon('${m.name}')">向该会员发放优惠券</button>`)}
function sendCoupon(name){modal(`<h2>定向发券</h2><p>接收会员：${name}</p><form onsubmit="event.preventDefault();issueCoupon('${name}',this.coupon.value)"><label class="field" style="margin-top:20px">选择优惠券<select name="coupon">${couponDefs.filter(c=>c.id!=='points').map(c=>`<option value="${c.id}">${c.title} · ¥${c.value}</option>`).join('')}</select></label><button class="btn wide">确认发放</button></form>`)}
function issueCoupon(name,id){if(name==='林小果'){if(!db.coupons.includes(id))db.coupons.push(id);db.usedCoupons=db.usedCoupons.filter(x=>x!==id);persist()}closeModal();render();toast(name==='林小果'?'已发放，可到商城会员中心查看':'已完成演示发券')}
function adminMarketing(){let list=db.activities.filter(a=>campaignTab==='全部活动'||a.type===campaignTab);return title('营销活动','把好优惠安排好，让顾客愿意常来。',`<button class="btn" onclick="activityForm()">＋ 创建活动</button>`)+`<div class="marketing-cards">${[['coupon','优惠券','精准发券，促进复购'],['gift','满减活动','阶梯优惠，提升客单'],['box','组合套餐','搭配售卖，省心实惠'],['clock','限时折扣','当季尝鲜，限时好价']].map(([ic,t,s])=>`<button class="marketing-type" onclick="activityForm(0,'${t}')"><span class="shortcut-icon">${I(ic)}</span><div><strong>${t}</strong><p>${s}</p></div></button>`).join('')}</div><div class="panel admin-panel"><div class="tabs" style="margin-top:0">${['全部活动','满减活动','优惠券','组合套餐','限时折扣'].map(t=>`<button class="${campaignTab===t?'active':''}" onclick="campaignTab='${t}';render()">${t}</button>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>活动名称</th><th>活动类型</th><th>优惠规则</th><th>活动时间</th><th>启用状态</th><th>操作</th></tr></thead><tbody>${list.map(a=>`<tr><td><strong>${E(a.name)}</strong></td><td><span class="pill">${a.type}</span></td><td>${a.type==='限时折扣'?a.off+'% 优惠':'满 ¥'+Y(a.min)+' 减 ¥'+Y(a.off)}</td><td><span class="tiny">${a.start}<br>${a.end}</span></td><td><button class="switch ${a.active?'on':''}" aria-label="${a.active?'停用':'启用'}${E(a.name)}" onclick="toggleActivity(${a.id})"></button></td><td><div class="table-actions"><button onclick="activityForm(${a.id})">编辑</button><button onclick="campaignPreview(${a.id})">预览</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无活动，创建一个新鲜优惠吧。</td></tr>'}</tbody></table></div></div><div class="notice" style="margin-top:20px">${I('info')}可保存活动、切换状态与审核配置表单。满减活动参与演示结算；其他类型先展示流程，复杂叠加规则待审核后实现。</div>`}
function toggleActivity(id){let a=db.activities.find(a=>a.id===id);a.active=!a.active;persist();render();toast(a.active?'活动已启用':'活动已停用')}
function activityForm(id=0,type='满减活动'){let a=db.activities.find(a=>a.id===id)||{name:'',type,min:99,off:10,start:'2026-10-31',end:'2026-11-30',active:true};modal(`<h2>${id?'编辑营销活动':'创建营销活动'}</h2><form onsubmit="saveActivity(event,${id})"><label class="field">活动名称<input name="name" value="${E(a.name)}" required maxlength="35" placeholder="例如：周末鲜果满减专场"></label><div class="form-grid"><label class="field">活动类型<select name="type">${['满减活动','优惠券','组合套餐','限时折扣'].map(t=>`<option ${a.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">适用范围<select name="scope"><option>全部商品</option><option>当季鲜果</option><option>指定商品（模板预览）</option></select></label><label class="field">优惠门槛（元）<input name="min" type="number" min="0" step="0.01" value="${a.min}" required></label><label class="field">减免金额 / 折扣百分比<input name="off" type="number" min="0.01" step="0.01" value="${a.off}" required></label><label class="field">开始日期<input name="start" type="date" value="${a.start}" required></label><label class="field">结束日期<input name="end" type="date" value="${a.end}" required></label></div><p>模板中满减按全场范围计算，其余范围、类型先保存配置用于审核。</p><button class="btn wide">保存并启用活动</button></form>`)}
function saveActivity(e,id){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));f.min=Number(f.min);f.off=Number(f.off);if(!f.name.trim()||f.end<f.start){toast('请检查活动名称和起止时间');return}if(f.type!=='限时折扣'&&f.off>=f.min){toast('减免金额应小于消费门槛');return}if(f.type==='限时折扣'&&f.off>=100){toast('折扣百分比应小于100');return}if(id)Object.assign(db.activities.find(a=>a.id===id),f,{active:true});else db.activities.unshift({...f,id:Date.now(),active:true});persist();closeModal();render();toast('活动已保存，可预览活动详情')}
function campaignPreview(id){let a=db.activities.find(a=>a.id===id);modal(`<div class="modal-hero"><div class="eyebrow">GUOYU FRESH · SPECIAL OFFER</div><h3 style="margin-top:15px">${E(a.name)}</h3><p>${a.type==='限时折扣'?a.off+'% 优惠':'满 ¥'+Y(a.min)+' 减 ¥'+Y(a.off)}</p></div><p>活动类型：${a.type}<br>活动时间：${a.start} 至 ${a.end}<br>状态：${a.active?'已启用':'已停用'}</p><button class="btn wide" onclick="closeModal();go('shop')">预览用户商城</button>`)}
function adminCommissions(){return title('分销佣金','每一笔推荐收益，都清楚记录、认真结算。')+`<div class="stats-grid">${stat('累计推广成交','¥12,826.50','chart','示例指标')}${stat('累计佣金','¥1,286.50','wallet','示例指标')}${stat('推广员人数','68 人','people','示例指标')}${stat('待审核提现',db.withdraw.filter(w=>w.status==='待审核').length+' 笔','orders','与商城推荐中心联动')}</div><div class="panel admin-panel"><div class="panel-title"><h3>提现审核</h3><button class="link" onclick="referralRules()">返佣规则 ${I('info')}</button></div><div class="table-scroll"><table><thead><tr><th>申请人</th><th>申请金额</th><th>提现方式</th><th>时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${db.withdraw.map(w=>`<tr><td><strong>${w.name}</strong></td><td class="orange">¥${M(w.amount)}</td><td>${w.channel}</td><td>${w.date}</td><td><span class="pill">${w.status}</span></td><td>${w.status==='待审核'?`<button class="btn small" onclick="auditWithdraw(${w.id})">审核申请</button>`:'已处理'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂时没有申请。可先在商城「分享赚佣」中提交一笔演示提现。</td></tr>'}</tbody></table></div></div><div class="panel admin-panel"><div class="panel-title"><h3>推广佣金记录</h3><span class="tiny muted">示例数据</span></div><div class="table-scroll"><table><thead><tr><th>推广员</th><th>来源订单</th><th>买家</th><th>佣金</th><th>状态</th></tr></thead><tbody>${referralRecords.map(r=>`<tr><td>林小果</td><td>${r.order}</td><td>${r.name}</td><td>¥${M(r.money)}</td><td><span class="pill">${r.status}</span></td></tr>`).join('')}</tbody></table></div></div>`}
function auditWithdraw(id){let w=db.withdraw.find(w=>w.id===id);modal(`<h2>审核提现申请</h2><p>申请人：${w.name}<br>金额：¥${M(w.amount)}<br>方式：${w.channel}</p><div class="notice" style="margin-top:20px">${I('info')}通过后只更新演示审核状态，不发起实际打款。</div><button class="btn wide" onclick="db.withdraw.find(w=>w.id===${id}).status='已审核 · 待演示打款';persist();closeModal();render();toast('已审核，未实际打款')">通过审核</button>`)}
function adminSettings(){let s=db.settings;return title('店铺设置','让品牌、服务与每一份新鲜，都有自己的样子。')+`<div class="settings-grid"><form class="panel" onsubmit="saveSettings(event)"><div class="panel-title"><h3>店铺基本信息</h3><span class="pill">本机演示配置</span></div><label class="field">店铺名称<input name="name" value="${E(s.name)}" required maxlength="30"></label><div class="form-grid"><label class="field">客服电话<input name="phone" value="${E(s.phone)}" required maxlength="25"></label><label class="field">营业时间<input name="hours" value="${E(s.hours)}" required maxlength="25"></label></div><label class="field">店铺简介<textarea name="desc" required maxlength="120">${E(s.desc)}</textarea></label><div class="form-grid"><label class="field">免配送门槛（元）<input name="free" value="${s.free}" type="number" min="0" required></label><label class="field">基础配送费（元）<input name="shipping" value="${s.shipping}" type="number" min="0" step="0.01" required></label></div><label class="field">配送服务<input name="delivery" value="${E(s.delivery)}" required maxlength="50"></label><button class="btn">保存店铺设置</button></form><div><div class="settings-preview"><span class="pill">商城展示预览</span><div><img src="assets/hero.jpg" alt="果屿鲜果门店品牌图"></div><h3>${E(s.name)}</h3><p>${E(s.desc)}</p><p>营业时间 ${E(s.hours)}<br>满 ¥${s.free} 免配送费</p><a class="btn outline small" href="#home">预览商城 ↗</a></div><div class="notice" style="margin-top:20px">${I('shield')}支付配置、员工权限和真实门店范围将在深度开发阶段接入。</div></div></div>`}
function saveSettings(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));f.free=Number(f.free);f.shipping=Number(f.shipping);db.settings=f;persist();render();toast('设置已保存，商城与结算已同步')}
function exportData(type){let list=type==='products'?db.products.map(p=>[p.id,p.name,p.category,p.price,p.stock,p.active?'在售':'下架']):db.orders.map(o=>[o.id,o.customer,o.name,o.total,o.status,o.date]);let columns=type==='products'?['编号','商品','分类','售价','库存','状态']:['订单号','客户','商品','实付','状态','时间'];let csv='\ufeff'+[columns,...list].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download='果屿-'+(type==='products'?'商品':'订单')+'-演示数据.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('演示数据已导出')}
function reviewNotes(){modal(`<h2>记录审核意见</h2><p>当前页面：${E(route)}。意见保存在当前浏览器，可导出后发给开发方。</p><form class="review-form" onsubmit="saveReview(event)"><label class="field">审核意见<textarea name="note" required minlength="2" maxlength="500" placeholder="例如：购物车希望增加配送时间选择；会员卡颜色再亮一些"></textarea></label><button class="btn wide">保存这条意见</button></form>${db.reviews.length?`<div class="modal-divider"></div><h3 style="font-size:13px">已记录 ${db.reviews.length} 条意见</h3>${db.reviews.map(r=>`<div class="ledger-row"><div><p style="margin-top:0">${E(r.page)} · ${E(r.time)}</p><p style="color:#536c42;font-size:11px;margin-top:6px">${E(r.note)}</p></div></div>`).join('')}<button class="btn outline wide" onclick="downloadReviews()">导出审核意见</button>`:''}`)}
function saveReview(e){e.preventDefault();let note=new FormData(e.target).get('note').trim();if(note.length<2){toast('请至少填写两个字');return}db.reviews.unshift({page:route,note,time:new Date().toLocaleString('zh-CN')});persist();reviewNotes();toast('审核意见已保存')}
function downloadReviews(){let content='# 果屿模板审核意见\n\n'+db.reviews.map(r=>`## ${r.page}\n${r.time}\n\n${r.note}\n`).join('\n');let url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='果屿模板审核意见.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){let admin=route.startsWith('admin/');document.getElementById('root').innerHTML=(admin?adminShell():reviewBar(false)+header()+`<main class="container">${({home,shop,cart:cartPage,checkout,success:successPage,member,orders:ordersPage,coupons:couponsPage,bundles:bundlesPage,referral:referralPage}[route]||home)()}</main>`+footer())+`<button class="review-drawer" onclick="reviewNotes()">${I('edit')}记录审核意见${db.reviews.length?' · '+db.reviews.length:''}</button>`}
function onRoute(){let next=location.hash.slice(1)||'home';if(next==='admin')next='admin/dashboard';if(next!==route){adminQuery='';adminFilter='全部'}route=next;closeModal();render();window.scrollTo({top:0,behavior:'instant'})}addEventListener('hashchange',onRoute);onRoute();let incoming=Number(new URLSearchParams(location.search).get('product'));if(P(incoming))detail(incoming);

function saveProfile(e){e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(!f.name.trim()){toast('请填写昵称');return}db.profile=f;persist();closeModal();render();toast('演示资料已保存')}
